{"command":"python - <<'EOF'
import os, urllib.request, urllib.error, urllib.parse

base = os.environ["ARTIFACT_SERVICE_URL"].rstrip("/")
token = os.environ["ARTIFACT_API_TOKEN"]

def call(method, path, headers=None):
    h = {"Authorization": f"Bearer {token}"}
    if headers: h.update(headers)
    req = urllib.request.Request(base + path, method=method, headers=h)
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            print(f"{method} {path} -> {r.status}")
            print(r.read(3000).decode())
    except urllib.error.HTTPError as e:
        print(f"{method} {path} -> HTTP {e.code}")
        print(e.read(3000).decode())
    except Exception as e:
        print(f"{method} {path} -> ERROR {type(e).__name__}: {e}")
    print("-" * 70)

for repo in ["pypi", "main", "default", "release", "artifact", "artifacts", "sqlite-utils"]:
    call("GET", f"/v1/quota?repository={urllib.parse.quote(repo)}&project=sqlite-utils")
call("GET", "/v1/projects/sqlite-utils/releases?repository=pypi")
EOF","description":"Probe repository names and header requirements"}

